using Cards;
using TMPro;
using UnityEngine;

namespace UI
{
    /// <summary>
    /// The icon vocabulary of the sidebars, in one asset (Resources/UIIconSet).
    ///
    /// The sidebars used to describe pacts and domains in sentences of 12pt text,
    /// which nobody could read on a phone. They now speak in icons, and every
    /// panel has to use the SAME icon for the same idea - so the set lives here
    /// rather than as loose sprite fields on each script.
    ///
    /// The art is generated by Tools/ArtGen (icons.js).
    /// </summary>
    [CreateAssetMenu(fileName = "UIIconSet", menuName = "Impocalypse/UI Icon Set")]
    public class UIIconSet : ScriptableObject
    {
        [Header("Resources")]
        public Sprite charwood;
        public Sprite bloodroot;
        public Sprite souls;
        public Sprite demonsilk;
        public Sprite soulwine;
        public Sprite ectoplasm;
        public Sprite anyResource;

        [Header("Scoring")]
        public Sprite strength;
        public Sprite wealth;
        public Sprite infamy;

        [Header("Board")]
        public Sprite tile;
        public Sprite domain;

        [Header("Pacts")]
        public Sprite pact;
        public Sprite treasure;

        [Header("Chrome")]
        [Tooltip("9-sliced recess used behind rows built in code (player cards).")]
        public Sprite panelInset;

        [Header("Lettering")]
        public TMP_FontAsset displayFont;

        private static UIIconSet _instance;
        private static bool _looked;

        /// <summary>Null if the asset is missing; callers fall back to text.</summary>
        public static UIIconSet Instance
        {
            get
            {
                if (_instance == null && !_looked)
                {
                    _instance = Resources.Load<UIIconSet>("UIIconSet");
                    _looked = true;
                    if (_instance == null)
                        Debug.LogWarning("[UIIconSet] Resources/UIIconSet not found - sidebars fall back to text.");
                }
                return _instance;
            }
        }

        public Sprite Resource(ResourceType r) => r switch
        {
            ResourceType.Wood => charwood,
            ResourceType.Carrot => bloodroot,
            ResourceType.Fish => souls,
            ResourceType.Special_A => demonsilk,
            ResourceType.Special_B => soulwine,
            ResourceType.Special_C => ectoplasm,
            ResourceType.WildcardCommon => anyResource,
            _ => null
        };
    }
}
